package com.saurabh.crm;
import com.saurabh.crm.user.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Bean; import org.springframework.security.crypto.password.PasswordEncoder;
@SpringBootApplication public class WiJungleCrmApplication {public static void main(String[] args){SpringApplication.run(WiJungleCrmApplication.class,args);}
 @Bean CommandLineRunner seedAdmin(UserRepository users,PasswordEncoder encoder,@Value("${app.bootstrap.admin-email}") String email,@Value("${app.bootstrap.admin-password}") String password){return args->{if(users.findByEmailIgnoreCase(email).isEmpty()){AppUser u=new AppUser();u.setFullName("CRM Administrator");u.setEmail(email.toLowerCase());u.setPasswordHash(encoder.encode(password));u.setRole(UserRole.ADMIN);u.setEnabled(true);users.save(u);System.out.println("Demo admin created: "+email+" — change credentials before deployment");}};}}
